import{_ as e,o as s,c as o,a5 as l}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"使用ts搭建一个react class组件","description":"sweetBoy 9126 2020.04.17 16:18 字数 554 阅读 524评论 0喜欢 0 1. 在父组件中给子组件传参在父组件中引入子组件，然后直接传入参数，子组件通过React.Component\\\\<Iprops\\\\ ，它里面的第一个泛型参数就是你父组件传来的参数。","frontmatter":{"title":"使用ts搭建一个react class组件","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","性能与实战"],"description":"sweetBoy 9126 2020.04.17 16:18 字数 554 阅读 524评论 0喜欢 0 1. 在父组件中给子组件传参在父组件中引入子组件，然后直接传入参数，子组件通过React.Component\\\\<Iprops\\\\ ，它里面的第一个泛型参数就是你父组件传来的参数。","sidebarWeight":15,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/应用/使用ts搭建一个react class组件.md"},"headers":[],"relativePath":"posts/React系统教程/05-性能与实战/使用ts搭建一个react class组件.md","filePath":"posts/React系统教程/05-性能与实战/使用ts搭建一个react class组件.md"}'),n={name:"posts/React系统教程/05-性能与实战/使用ts搭建一个react class组件.md"};function a(i,t,r,p,c,u){return s(),o("div",null,[...t[0]||(t[0]=[l('<div><h1 id="使用ts搭建一个react-class组件" tabindex="-1">使用ts搭建一个react class组件 <a class="header-anchor" href="#使用ts搭建一个react-class组件" aria-label="Permalink to &quot;使用ts搭建一个react class组件&quot;">​</a></h1><blockquote><p>本节目标：理解“使用ts搭建一个react class组件”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <a href="https://www.jianshu.com/u/56540ed9f123" target="_blank" rel="noreferrer"></a></p></blockquote><p><a href="https://www.jianshu.com/u/56540ed9f123" target="_blank" rel="noreferrer">sweetBoy_9126</a> 2020.04.17 16:18 字数 554 阅读 524评论 0喜欢 0</p><ol><li>在父组件中给子组件传参在父组件中引入子组件，然后直接传入参数，子组件通过React.Component&lt;Iprops&gt;，它里面的第一个泛型参数就是你父组件传来的参数</li><li>App.tsx</li></ol><p>import React, { Component } from &#39;react&#39;;import Button from &#39;./componets/button&#39; class App extends Component { render() { return ( &lt;div className=&quot;App&quot;&gt; &lt;Button&gt;小改改&lt;/Button&gt; &lt;/div&gt; ) }}</p><ul><li>button.tsx</li></ul><p>import React from &#39;react&#39;import &#39;./button.css&#39;interface Iprops { size: string}class Button extends React.Component&lt;Iprops&gt;{ render() { return ( &lt;div className=&quot;button&quot;&gt;{this.props.children}&lt;/div&gt; ) }}export default Button</p><ol><li>设置组件里的私有属性组件中的私有属性就是React.Component&lt;&gt;里面的第二个参数</li></ol><p>interface IState { n: number}class Button extends React.Component&lt;Iprops, IState&gt;{ constructor(props: Iprops) { super(props) this.state = { n: 1 } } render() { return ( &lt;div className=&quot;button&quot;&gt; {this.state.n} &lt;/div&gt; ) }}</p><ol><li>修改react开发者工具里组件的名字</li></ol><p>我们现在的组件名字是Button，如果我们想修改它只需要在对应组件中修改它静态资源的displayName class Button extends React.Component&lt;Iprops, IState&gt;{ static displayName = &#39;LifaButton&#39;}</p><ol><li>设置组件的props的默认值当我们没有在父组件中传给子组件props时，我们可以在子组件中通过defaultProps来设置它的默认值</li></ol><p>class Button extends React.Component&lt;Iprops, IState&gt;{ static defaultProps = { size: &#39;normal&#39; }} 问题：在我们不传的时候，我们设置默认值，可能在使用的时候会报错，比如</p><p>它会报size有可能是undefined，解决方法强制指定类型为string this.props.size as string + 1</p><ol><li>触发父组件中的点击事件(1). 在子组件中的props对应的接口里定义onClick类型为React.MouseEventHandler(2). 父组件中传入onClick，并声明对应的onClick事件，事件里的event类型指定为React.MouseEvent(3). 子组件里的onClick调用父组件传来的onClick</li><li>App.tsx</li></ol><p>class App extends Component { onClick(e: React.MouseEvent) { console.log(e) } render() { return ( &lt;div className=&quot;App&quot;&gt; &lt;Button onClick={this.onClick}&gt;哈哈哈小改改&lt;/Button&gt; &lt;/div&gt; ) }}</p><ul><li>button.tsx</li></ul><p>interface Iprops { onClick: React.MouseEventHandler}class Button extends React.Component&lt;Iprops&gt; { render( &lt;div className=&quot;button&quot; onClick={this.props.onClick}&gt;&lt;/div&gt; )} 问题： 上面的e: React.MouseEvent，我们直接打印出e.target是当前的div标签，div可以设置style，所以我们尝试打印出e.target.style，但是我们发现会报错，因为它认为e.target有可能是undefined。 解决办法：</p><ol><li>指定e.target类型为HTMLDIVElement</li></ol><p>e.target as HTMLDivElement).style</p><ol><li>直接为e指定React.MouseEvent&lt;HTMLDivElement&gt;</li></ol><p>onClick(e: React.MouseEvent&lt;HTMLDivElement&gt;) { const div = e.currentTarget console.log(div.style.width) }</p><ol><li>this问题，react里默认this是undefined，如果需要对属性进行操作，需要使用箭头函数，或者绑定它的this写法1：</li></ol><p>class Button extends React.Component&lt;Iprops, IState&gt;{ static displayName = &#39;LifaButton&#39; static defaultProps = { size: &#39;normal&#39; } constructor(props: Iprops) { super(props) this.state = { n: 1 } } // 使用箭头函数让this等于外界的this onClick= ()=&gt; { this.setState({ n: this.state.n + 1 }) } render() { return ( &lt;div className=&quot;button&quot; onClick={this.onClick}&gt; {this.props.children} {this.state.n} &lt;/div&gt; ) }} 写法2： onClick(){ this.setState({ n: this.state.n + 1 }) } render() { return ( &lt;div className=&quot;button&quot; onClick={this.onClick.bind(this)}&gt; {this.props.children} {this.state.n} &lt;/div&gt; ) } 总结：</p><ol><li>React.Compoent&lt;&gt;里的第一个参数是props的类型，第二个是state的类型</li><li>如果需要绑定click事件，你需要声明onClick类型为React.Mouse(事件类型)EventHandler</li><li>onClick两种写法：(1). 旧语法加bind this.onClick.bind(this)(2). 直接箭头函数 &gt; 来自 &lt;<a href="https://www.jianshu.com/p/ed9509025699/" target="_blank" rel="noreferrer">https://www.jianshu.com/p/ed9509025699/</a>&gt;</li></ol></div>',1)])])}const g=e(n,[["render",a]]);export{m as __pageData,g as default};
